_PHASES = (
    "понятия и границы",
    "разбор примеров",
    "алгоритм решения",
    "реализация в проекте",
    "проверка результата",
    "рефакторинг решения",
    "анализ ограничений",
    "итоговый маршрут",
)


def _expand_schedule() -> tuple[ProgramSession, ...]:
    sessions: list[ProgramSession] = []
    for block, topic, kind, hours, goal, keywords in _SCHEDULE:
        parts = hours // 2
        for part in range(parts):
            phase = _PHASES[part]
            title = topic if parts == 1 else f"{topic}: {phase}"
            sessions.append(
                ProgramSession(
                    len(sessions) + 1,
                    title,
                    kind,
                    block,
                    f"{goal}; этап: {phase}",
                    keywords,
                    phase,
                )
            )
    return tuple(sessions)


SESSIONS = _expand_schedule()
